/**
 * Movimiento del jugador sobre el mapa del pueblo (Nivel 2).
 *
 * Reemplaza la vieja "fila de botones" de la pulpería por un mapa que se
 * recorre de verdad con WASD o las flechas: el jugador es un puntito que
 * se mueve sobre la ilustración del pueblo y, al acercarse a un
 * personaje, puede hablarle con ESPACIO (o clic, que sigue funcionando
 * igual que antes).
 *
 * El Baqueano es el único que puede indicar el camino de salida del
 * pueblo, así que se lo marca como "bloqueado" (visualmente esquivo, sin
 * poder hablarle) hasta que los otros tres testigos ya fueron
 * interrogados. La decisión de bloquear la interacción de verdad vive en
 * GestorInterrogatorio (que es quien conoce las reglas del nivel); este
 * gestor solo se encarga de mover al jugador, detectar cercanía y avisar
 * visualmente cuál personaje todavía no se puede abrir.
 */

import { establecerTexto } from '../Compartido/interfaz.js';

const VELOCIDAD_PX_POR_SEG = 295;
const esDispositivoTactil = () => window.matchMedia('(pointer: coarse)').matches;
const obtenerVelocidadMovimiento = () => esDispositivoTactil() ? 165 : VELOCIDAD_PX_POR_SEG;
const RADIO_INTERACCION_MUNDO = 68;
const TECLAS_MOVIMIENTO = new Set(['w', 'a', 's', 'd', 'arrowup', 'arrowdown', 'arrowleft', 'arrowright']);
const TECLA_ENTRAR = 'e';

// El "mundo" (#mundo-dos) es más grande que la ventana visible
// (#game-world-dos): ZOOM_MUNDO define cuánto. La cámara después vuelve
// a agrandar ese mundo sobre la pantalla con ZOOM_CAMARA. Son dos zooms
// independientes a propósito: ZOOM_MUNDO controla cuánto mapa entra en
// pantalla (cuánto hay que caminar), ZOOM_CAMARA controla qué tan cerca
// se ve todo. Subir ZOOM_CAMARA agranda la escena sin cambiar el
// recorrido; subir ZOOM_MUNDO agranda el recorrido sin cambiar el
// acercamiento visual.
const ZOOM_MUNDO = 1.12;
const ZOOM_CAMARA = 2.0;
// Proporción nativa del mapa del pueblo (1376 × 768). El mundo nunca debe
// adoptar la proporción del celular: eso estira el fondo y desplaza a los NPC.
const PROPORCION_MAPA = 1376 / 768;

