class GestorMapa {
  constructor({ elementos, estado, alInteractuar, audio }) {
    this.elementos = elementos;
    this.audio = audio;
    this.estado = estado;
    this.alInteractuar = alInteractuar;

    this.teclasPresionadas = new Set();
    this.activo = false;
    this.pausado = false;
    this.liberarJoystick = null;
    this.ultimoTiempo = null;
    this.tiempoAnimacion = 0;
    this.marcoAnimacion = 0;
    this.personajeCercano = null;
    this.dentroPulperia = false;

    // Precarga los 64 cuadros normalizados antes de alternarlos como fondos CSS.
    // Evita que el navegador muestre un fondo vacío durante la primera descarga.
    this.spritesCaminataListos = false;
    this.spritesCaminataCargados = new Map();
    this.promesaPrecargaSprites = this.precargarSpritesCaminata();

    // Posición del jugador en px DEL MUNDO (no % de pantalla, no px de
    // viewport). Se inicializa de verdad en iniciar(), una vez que ya
    // conocemos el tamaño real del mundo.
    this.posicion = { x: 0, y: 0 };
    this.mundoAncho = 0;
    this.mundoAlto = 0;

    this.alPresionarTecla = this.alPresionarTecla.bind(this);
    this.alSoltarTecla = this.alSoltarTecla.bind(this);
    this.alRedimensionar = this.alRedimensionar.bind(this);
  }

  /** Engancha los listeners de teclado y de resize una sola vez, al armar el nivel. */
  inicializarEventos() {
    // Captura antes que otros gestores para que el foco de botones/modales
    // no intercepte WASD ni las flechas mientras el mapa está activo.
    window.addEventListener('keydown', this.alPresionarTecla, true);
    window.addEventListener('keyup', this.alSoltarTecla);
    this.configurarControlesTactiles();
    window.addEventListener('blur', () => this.teclasPresionadas.clear());
    document.addEventListener('visibilitychange', () => { if (document.hidden) this.teclasPresionadas.clear(); });
    window.addEventListener('resize', this.alRedimensionar);
  }

  /**
   * Si la ventana cambia de tamaño, el mundo (que depende del viewport
   * vía ZOOM_MUNDO) también cambia, así que hay que recalcularlo y
   * reubicar tanto al jugador (para que no quede "flotando" en un %
   * que ya no corresponde) como la cámara.
   */
  alRedimensionar() {
    if (!this.activo || !this.mundoAncho || !this.mundoAlto) return;
    const xPorcentaje = this.posicion.x / this.mundoAncho;
    const yPorcentaje = this.posicion.y / this.mundoAlto;
    this.calcularTamanioMundo();
    this.posicion.x = xPorcentaje * this.mundoAncho;
    this.posicion.y = yPorcentaje * this.mundoAlto;
    this.aplicarPosicion();
    this.actualizarCamara();
  }

  /**
   * Fija el tamaño en px de #mundo-dos a partir del tamaño actual del
   * visor (#game-world-dos) multiplicado por ZOOM_MUNDO. Hay que
   * llamarla antes de convertir cualquier % a px del mundo.
   */
  calcularTamanioMundo() {
    const rect = this.elementos.escenaMundo.getBoundingClientRect();
    if (!rect.width || !rect.height) return;

    const anchoViewport = rect.width;
    const altoViewport = rect.height;

    // El mapa conserva siempre su relación de aspecto original. Se escala
    // lo suficiente para cubrir el visor y se amplía con el zoom de mundo.
    this.mundoAncho = Math.max(anchoViewport, altoViewport * PROPORCION_MAPA) * ZOOM_MUNDO;
    this.mundoAlto = this.mundoAncho / PROPORCION_MAPA;

    this.elementos.mundoMapa.style.width = `${this.mundoAncho}px`;
    this.elementos.mundoMapa.style.height = `${this.mundoAlto}px`;
  }

  async precargarSpritesCaminata() {
    const jugador = this.elementos.jugadorMapa;
    if (!jugador) return false;

    // Leer las URL de las propiedades CSS evita duplicar rutas y garantiza
    // que se precarguen exactamente los 64 PNG normalizados usados por el nivel.
    const estilos = getComputedStyle(jugador);
    const hojaSprites = [...document.styleSheets].find((hoja) => {
      try { return hoja.href && new URL(hoja.href).pathname.endsWith('/nivelDos.css'); }
      catch (_) { return false; }
    });
    const baseSprites = hojaSprites?.href || new URL('../../CSS/Nivel%202/nivelDos.css', import.meta.url).href;
    const direcciones = [
      'north', 'south', 'east', 'west',
      'north-east', 'north-west', 'south-east', 'south-west'
    ];

    const cargarImagen = async (url) => {
      // Reintentar fallos transitorios. No se permite alternar a un PNG
      // mientras su descarga o decodificación siga pendiente.
      for (let intento = 0; intento < 3; intento++) {
        const imagen = new Image();
        const resultado = await new Promise((resolver) => {
          imagen.onload = () => resolver(true);
          imagen.onerror = () => resolver(false);
          imagen.src = url;
          if (imagen.complete && imagen.naturalWidth > 0) resolver(true);
        });
        if (resultado && imagen.naturalWidth > 0) {
          try { if (imagen.decode) await imagen.decode(); } catch (_) { /* onload ya confirmó el recurso */ }
          if (imagen.naturalWidth > 0) return imagen;
        }
        await new Promise((resolver) => setTimeout(resolver, 80 * (intento + 1)));
      }
      return null;
    };

    const tareas = [];
    for (const direccion of direcciones) {
      for (let cuadro = 0; cuadro < 8; cuadro++) {
        const valor = estilos.getPropertyValue(`--sprite-${direccion}${cuadro}`).trim();
        const coincidencia = valor.match(/url\(["']?(.*?)["']?\)/);
        if (!coincidencia) continue;
        const url = new URL(coincidencia[1], baseSprites).href;
        tareas.push((async () => {
          const imagen = await cargarImagen(url);
          if (imagen) this.spritesCaminataCargados.set(`${direccion}${cuadro}`, imagen);
          return Boolean(imagen);
        })());
      }
    }

    const resultados = await Promise.all(tareas);
    this.spritesCaminataListos = resultados.length === 64 && resultados.every(Boolean)
      && this.spritesCaminataCargados.size === 64;
    return this.spritesCaminataListos;
  }

  alPresionarTecla(evento) {
    if (!this.activo || this.pausado || this.elementos.juegoPantalla.classList.contains('hidden')) return;
    const tecla = evento.key.toLowerCase();

    if (tecla === TECLA_ENTRAR) {
      evento.preventDefault();
      if (this.personajeCercano !== null) this.alInteractuar(this.personajeCercano);
      else this.alternarPulperia();
      return;
    }

    if (TECLAS_MOVIMIENTO.has(tecla)) {
      evento.preventDefault();
      this.teclasPresionadas.add(tecla);
    }

    if ((tecla === ' ' || tecla === 'enter') && this.personajeCercano !== null) {
      evento.preventDefault();
      this.alInteractuar(this.personajeCercano);
    }
  }

  alSoltarTecla(evento) {
    this.teclasPresionadas.delete(evento.key.toLowerCase());
  }

  configurarControlesTactiles() {
    const joystick = document.getElementById('joystick-nivel-dos');
    const botonA = document.getElementById('boton-a-nivel-dos');
    const botonB = document.getElementById('boton-b-nivel-dos');
    if (joystick) {
      let teclasActivas = new Set();
      const actualizar = (evento) => {
        if (!this.activo || this.pausado) return;
        const rect = joystick.getBoundingClientRect();
        const dx = (evento.clientX - (rect.left + rect.width / 2)) / (rect.width / 2);
        const dy = (evento.clientY - (rect.top + rect.height / 2)) / (rect.height / 2);
        const nuevas = new Set();
        if (Math.abs(dx) > .28) nuevas.add(dx < 0 ? 'a' : 'd');
        if (Math.abs(dy) > .28) nuevas.add(dy < 0 ? 'w' : 's');
        teclasActivas.forEach((tecla) => { if (!nuevas.has(tecla)) this.teclasPresionadas.delete(tecla); });
        nuevas.forEach((tecla) => this.teclasPresionadas.add(tecla));
        teclasActivas = nuevas;
        const perilla = joystick.querySelector('span');
        if (perilla) perilla.style.transform = `translate(${Math.max(-18, Math.min(18, dx * 18))}px,${Math.max(-18, Math.min(18, dy * 18))}px)`;
      };
      const soltar = () => {
        teclasActivas.forEach((tecla) => this.teclasPresionadas.delete(tecla));
        teclasActivas.clear();
        const perilla = joystick.querySelector('span');
        if (perilla) perilla.style.transform = 'translate(0,0)';
      };
      joystick.addEventListener('pointerdown', (evento) => {
        evento.preventDefault();
        if (!this.activo || this.pausado) return;
        joystick.setPointerCapture?.(evento.pointerId);
        actualizar(evento);
      });
      joystick.addEventListener('pointermove', (evento) => {
        if (evento.buttons && !this.pausado) actualizar(evento);
      });
      ['pointerup', 'pointercancel', 'lostpointercapture'].forEach((tipo) => joystick.addEventListener(tipo, soltar));
      this.liberarJoystick = soltar;
    }
    if (botonA) {
      botonA.addEventListener('pointerdown', (evento) => {
        evento.preventDefault();
        if (!this.activo || this.pausado) return;
        if (this.personajeCercano !== null) this.alInteractuar(this.personajeCercano);
      });
      botonA.addEventListener('click', (evento) => evento.preventDefault());
    }
    if (botonB) {
      botonB.addEventListener('pointerdown', (evento) => {
        evento.preventDefault();
        if (!this.activo || this.pausado) return;
        window.dispatchEvent(new KeyboardEvent('keydown', { key: 'e', bubbles: true, cancelable: true }));
      });
      botonB.addEventListener('click', (evento) => evento.preventDefault());
    }
  }

  /** Pone al jugador en su punto de partida y arranca el bucle de movimiento. */
  iniciar() {
    this.calcularTamanioMundo();
    this.pausado = false;

    // Punto de partida libre de obstáculos. El antiguo x=18% caía dentro
    // del poste/tranquera (x=18–19.5%), por eso el jugador aparecía atrapado.
    // Se coloca en el camino despejado a la izquierda del poste.
    this.dentroPulperia = false;
    this.elementos.mundoMapa.classList.remove('interior-pulperia');
    this.elementos.jugadorMapa.classList.remove('jugador-interior');
    this.posicion = {
      x: (15 / 100) * this.mundoAncho,
      y: (82 / 100) * this.mundoAlto
    };

    this.aplicarPosicion();
    this.actualizarCamara();
    this.personajeCercano = null;
    this.teclasPresionadas.clear();
    this.ultimoTiempo = null;
    this.tiempoAnimacion = 0;
    this.marcoAnimacion = 0;
    this.elementos.jugadorMapa.dataset.direccion = 'south';
    this.actualizarSpriteJugador(false);
    this.activo = true;
    requestAnimationFrame((tiempo) => this.recorrerBucle(tiempo));
  }

  /** Frena el movimiento (se llama al salir del nivel del todo). */
  detener() {
    this.activo = false;
    this.pausado = false;
    this.teclasPresionadas.clear();
    this.liberarJoystick?.();
  }

  establecerPausa(pausado) {
    this.pausado = Boolean(pausado);
    this.teclasPresionadas.clear();
    this.liberarJoystick?.();
    this.ultimoTiempo = null;
  }

  recorrerBucle(tiempo) {
    if (!this.activo) return;
    if (this.pausado) {
      this.ultimoTiempo = null;
      requestAnimationFrame((t) => this.recorrerBucle(t));
      return;
    }

    // Mientras el jugador está adentro del minijuego de un personaje, la
    // escena del mundo queda oculta: el bucle sigue vivo pero no mueve
    // ni gasta tiempo, así al volver no hay ningún salto raro.
    if (this.elementos.juegoPantalla.classList.contains('hidden')) {
      this.ultimoTiempo = null;
      requestAnimationFrame((t) => this.recorrerBucle(t));
      return;
    }

    const delta = this.ultimoTiempo === null ? 0 : Math.min(0.05, (tiempo - this.ultimoTiempo) / 1000);
    this.ultimoTiempo = tiempo;

    this.mover(delta);
    this.actualizarProximidad();

    requestAnimationFrame((t) => this.recorrerBucle(t));
  }

  mover(delta) {
    if (delta <= 0) return;
    if (!this.mundoAncho || !this.mundoAlto) return;

    let dx = 0;
    let dy = 0;
    if (this.teclasPresionadas.has('a') || this.teclasPresionadas.has('arrowleft')) dx -= 1;
    if (this.teclasPresionadas.has('d') || this.teclasPresionadas.has('arrowright')) dx += 1;
    if (this.teclasPresionadas.has('w') || this.teclasPresionadas.has('arrowup')) dy -= 1;
    if (this.teclasPresionadas.has('s') || this.teclasPresionadas.has('arrowdown')) dy += 1;

    if (dx === 0 && dy === 0) {
      this.elementos.jugadorMapa.classList.remove('jugador-caminando');
      this.actualizarSpriteJugador(false);
      return;
    }
    this.elementos.jugadorMapa.classList.add('jugador-caminando');
    this.elementos.jugadorMapa.dataset.direccion =
      dy < 0 ? (dx < 0 ? 'north-west' : dx > 0 ? 'north-east' : 'north') :
      dy > 0 ? (dx < 0 ? 'south-west' : dx > 0 ? 'south-east' : 'south') :
      (dx < 0 ? 'west' : 'east');

    // Normalizar para que moverse en diagonal no sea más rápido. La
    // velocidad se mide en px del MUNDO por segundo, así que no depende
    // del zoom de cámara (subir ZOOM_CAMARA no hace correr más rápido
    // ni más lento al personaje, solo se ve todo más grande).
    this.actualizarSpriteJugador(true, delta);
    const largo = Math.hypot(dx, dy) || 1;
    const desplazamientoX = (dx / largo) * obtenerVelocidadMovimiento() * delta;
    const desplazamientoY = (dy / largo) * obtenerVelocidadMovimiento() * delta;

    // Límites del recuadro del mapa, iguales a los de antes (3%-96% en
    // X, 14%-96% en Y) pero ahora expresados en px del mundo.
    const limiteXMin = 0.03 * this.mundoAncho;
    const limiteXMax = 0.96 * this.mundoAncho;
    const limiteYMin = 0.14 * this.mundoAlto;
    const limiteYMax = 0.96 * this.mundoAlto;

    const xPropuesto = Math.min(limiteXMax, Math.max(limiteXMin, this.posicion.x + desplazamientoX));
    const yPropuesto = Math.min(limiteYMax, Math.max(limiteYMin, this.posicion.y + desplazamientoY));

    // Cada eje se resuelve por separado: así, si el jugador choca de
    // frente contra un edificio en diagonal, igual puede "deslizarse"
    // por el borde en el eje libre, en vez de quedar trabado.
    if (!this.colisionaConEdificio(xPropuesto, this.posicion.y)
        && !this.colisionaConPersonaje(xPropuesto, this.posicion.y)) {
      this.posicion.x = xPropuesto;
    }
    if (!this.colisionaConEdificio(this.posicion.x, yPropuesto)
        && !this.colisionaConPersonaje(this.posicion.x, yPropuesto)) {
      this.posicion.y = yPropuesto;
    }

    this.aplicarPosicion();
    this.actualizarCamara();
  }

  /** Cambia entre el pueblo y el interior al usar E cerca de una puerta. */
  alternarPulperia() {
    // La entrada/salida se obtiene de la matriz: 2 = puerta.
    // Así, al mover un 2 en la matriz correspondiente, se mueve también
    // la zona donde E permite cambiar de mapa.
    const matriz = this.dentroPulperia
      ? MAPA_COLISIONES_INTERIOR
      : MAPA_COLISIONES_MUNDO;
    const xPct = (this.posicion.x / this.mundoAncho) * 100;
    const yPct = (this.posicion.y / this.mundoAlto) * 100;
    const filaJugador = Math.floor(yPct);
    const columnaJugador = Math.floor(xPct);
    const radioPuerta = 2;
    let cercaDePuerta = false;

    for (let fila = Math.max(0, filaJugador - radioPuerta);
         fila <= Math.min(matriz.length - 1, filaJugador + radioPuerta);
         fila++) {
      for (let columna = Math.max(0, columnaJugador - radioPuerta);
           columna <= Math.min(matriz[fila].length - 1, columnaJugador + radioPuerta);
           columna++) {
        if (matriz[fila]?.[columna] === 2) {
          cercaDePuerta = true;
          break;
        }
      }
      if (cercaDePuerta) break;
    }

    if (!cercaDePuerta) {
      establecerTexto(
        this.elementos.pistaInteraccion,
        esDispositivoTactil() ? 'ACERCATE A LA PUERTA Y PRESIONÁ B' : 'ACERCATE A LA PUERTA Y PRESIONÁ E'
      );
      return;
    }

    const centroPuerta = (mapa) => {
      const celdas = [];
      mapa.forEach((fila, indiceFila) => fila.forEach((valor, indiceColumna) => {
        if (valor === 2) celdas.push({ x: indiceColumna + 0.5, y: indiceFila + 0.5 });
      }));
      if (!celdas.length) return { x: this.mundoAncho * 0.5, y: this.mundoAlto * 0.5 };
      const centro = celdas.reduce((acum, celda) => ({ x: acum.x + celda.x, y: acum.y + celda.y }), { x: 0, y: 0 });
      return { x: (centro.x / celdas.length / mapa[0].length) * this.mundoAncho,
        y: (centro.y / celdas.length / mapa.length) * this.mundoAlto };
    };

    if (!this.dentroPulperia) {
      this.dentroPulperia = true;
      // La matriz interior contiene varias puertas/aberturas. Promediarlas
      // dejaba al jugador en una pared. La entrada de la pulpería está en
      // el sector izquierdo; lo ubicamos unos pasos adentro, sobre piso libre.
      this.posicion = {
        x: this.mundoAncho * 0.24,
        y: this.mundoAlto * 0.44
      };
      this.audio?.reproducirPuerta();
      this.elementos.mundoMapa.classList.add('interior-pulperia');
      this.elementos.jugadorMapa.classList.add('jugador-interior');
      document.querySelectorAll('.personaje').forEach((p) => {
        const esCantor = Number(p.dataset.personaje) === 3;
        p.style.display = esCantor ? 'block' : 'none';
        p.classList.toggle('personaje-cantor-interior', esCantor);
      });
      this.personajeCercano = null;
      establecerTexto(this.elementos.pistaInteraccion, esDispositivoTactil()
        ? 'ESTÁS EN LA PULPERÍA · ACERCATE AL CANTOR Y PRESIONÁ A'
        : 'ESTÁS EN LA PULPERÍA · ACERCATE AL CANTOR Y PRESIONÁ ESPACIO PARA HABLAR');
    } else {
      this.dentroPulperia = false;
      // Salir exactamente junto a la puerta exterior del pueblo.
      this.posicion = centroPuerta(MAPA_COLISIONES_MUNDO);
      this.audio?.reproducirPuerta();
      this.elementos.mundoMapa.classList.remove('interior-pulperia');
      this.elementos.jugadorMapa.classList.remove('jugador-interior');
      document.querySelectorAll('.personaje').forEach((p) => {
        p.style.display = '';
        p.classList.remove('personaje-cantor-interior');
      });
      this.personajeCercano = null;
      establecerTexto(this.elementos.pistaInteraccion, esDispositivoTactil()
        ? 'VOLVISTE AL PUEBLO · ACERCATE A UN PERSONAJE Y PRESIONÁ A'
        : 'VOLVISTE AL PUEBLO · ACERCATE A UN PERSONAJE PARA HABLAR');
    }

    // Si se cambió el tamaño de pantalla mientras estábamos dentro, al volver
    // al pueblo se vuelven a calcular las posiciones de los NPC sobre el mundo actual.
    this.aplicarPosicion();
    this.actualizarCamara();
  }

  /** Comprueba la huella del jugador contra la matriz de celdas.
   *  0 = piso libre, 1 = pared/obstáculo, 2 = puerta transitable.
   */
  colisionaConEdificio(x, y) {
    if (!this.mundoAncho || !this.mundoAlto) return false;

    const matriz = this.dentroPulperia
      ? MAPA_COLISIONES_INTERIOR
      : MAPA_COLISIONES_MUNDO;
    const filas = matriz.length;
    const columnas = matriz[0].length;

    const xPct = (x / this.mundoAncho) * 100;
    const yPct = (y / this.mundoAlto) * 100;
    // Huella física pequeña y constante: el tamaño visual del sprite no
    // agranda la colisión ni impide pasar por los caminos existentes.
    // No se modifica la matriz de colisiones del mapa.
    const radioX = (9 / this.mundoAncho) * 100;
    const radioY = (5 / this.mundoAlto) * 100;
    const minX = Math.max(0, Math.floor(xPct - radioX));
    const maxX = Math.min(columnas - 1, Math.floor(xPct + radioX));
    const minY = Math.max(0, Math.floor(yPct - radioY));
    const maxY = Math.min(filas - 1, Math.floor(yPct + radioY * 0.35));

    for (let fila = minY; fila <= maxY; fila++) {
      for (let columna = minX; columna <= maxX; columna++) {
        // La puerta (2) se puede atravesar; solo las celdas 1 bloquean.
        if (matriz[fila]?.[columna] === 1) return true;
      }
    }
    return false;
  }

  /** Evita que el jugador atraviese a los NPC visibles sin bloquear
   *  el acceso a su zona de interacción. La huella es ovalada y pequeña.
   */
  colisionaConPersonaje(x, y) {
    const personajes = this.elementos.mundoMapa.querySelectorAll('.personaje');
    for (const personaje of personajes) {
      if (getComputedStyle(personaje).display === 'none') continue;
      const indice = Number(personaje.dataset.personaje);
      if ((this.dentroPulperia && indice !== 3) || (!this.dentroPulperia && indice === 3)) continue;

      // El contenedor del NPC incluye la etiqueta debajo del sprite y usa
      // translate(-50%, -100%). Su offsetTop marca el punto de apoyo del
      // contenedor completo, no los pies del dibujo: descontamos la parte
      // ocupada por la etiqueta para alinear la colisión con el cuerpo.
      const figura = personaje.querySelector('.personaje-figura');
      const altoFigura = figura?.offsetHeight || personaje.offsetHeight;
      const baseX = personaje.offsetLeft;
      const baseY = personaje.offsetTop - personaje.offsetHeight + altoFigura;
      const radioX = this.dentroPulperia && indice === 3 ? 38 : 34;
      const radioY = this.dentroPulperia && indice === 3 ? 27 : 23;
      const distanciaX = (x - baseX) / radioX;
      const distanciaY = (y - baseY) / radioY;
      if ((distanciaX * distanciaX) + (distanciaY * distanciaY) < 1) return true;
    }
    return false;
  }

  actualizarSpriteJugador(caminando, delta = 0) {
    const jugador = this.elementos.jugadorMapa;
    const direccion = jugador.dataset.direccion || 'south';
    if (!caminando) {
      jugador.style.setProperty('--sprite-frame-actual', `var(--sprite-${direccion}, var(--sprite-abajo, none))`);
      this.tiempoAnimacion = 0;
      this.marcoAnimacion = 0;
      return;
    }
    // Si la precarga aún no terminó, no cambiar el fondo: se mantiene visible
    // el último sprite válido en lugar de mostrar un hueco entre descargas.
    if (!this.spritesCaminataListos) return;

    this.tiempoAnimacion += delta;
    while (this.tiempoAnimacion >= 0.12) {
      this.tiempoAnimacion -= 0.12;
      this.marcoAnimacion = (this.marcoAnimacion + 1) % 8;
    }
    const imagen = this.spritesCaminataCargados.get(`${direccion}${this.marcoAnimacion}`);
    if (!imagen || !imagen.complete || !imagen.naturalWidth) return;
    // Usar la URL del objeto Image ya decodificado, no volver a resolver
    // una custom property CSS en cada frame.
    jugador.style.setProperty('--sprite-frame-actual', `url("${imagen.src}")`);
  }

  aplicarPosicion() {
    const jugador = this.elementos.jugadorMapa;
    jugador.style.left = `${this.posicion.x}px`;
    jugador.style.top = `${this.posicion.y}px`;

    // Profundidad tipo RPG: el personaje cuyo punto de apoyo está más
    // abajo en el mapa se dibuja por delante. Así el jugador puede pasar
    // delante del Cantor o quedar detrás de él según su posición real.
    if (this.dentroPulperia && this.mundoAlto) {
      const cantor = this.elementos.mundoMapa.querySelector(
        '.personaje-cantor.personaje-cantor-interior'
      );
      const baseProfundidad = 100;
      jugador.style.zIndex = String(baseProfundidad + Math.round(this.posicion.y));
      if (cantor) {
        const posicionYCanon = this.mundoAlto * 0.68;
        cantor.style.zIndex = String(baseProfundidad + Math.round(posicionYCanon));
      }
    } else {
      jugador.style.removeProperty('z-index');
    }
  }

  /**
   * Mueve y escala #mundo-dos para que el jugador quede centrado en la
   * pantalla, con zoom ZOOM_CAMARA. #mundo-dos tiene transform-origin
   * en 0 0 (ver nivelDos.css), así que un punto (x, y) del mundo cae en
   * pantalla en (offsetX + x*ZOOM_CAMARA, offsetY + y*ZOOM_CAMARA).
   * Para centrar al jugador despejamos offsetX/offsetY de esa fórmula
   * pidiendo que el punto del jugador caiga en el centro del visor.
   */
  actualizarCamara() {
    if (!this.mundoAncho || !this.mundoAlto) return;

    const rectEscena = this.elementos.escenaMundo.getBoundingClientRect();
    const centroX = rectEscena.width / 2;
    const centroY = rectEscena.height / 2;

    // El encuadre visual es idéntico en PC, celulares y tablets.
    // Los controles táctiles no deben cambiar el zoom ni la escala del mundo:
    // solo cambia la forma de entrada (joystick/botones frente a teclado).
    const zoomCamara = this.dentroPulperia ? 1.5 : ZOOM_CAMARA;
    let offsetX = centroX - this.posicion.x * zoomCamara;
    let offsetY = centroY - this.posicion.y * zoomCamara;

    // Clamp para no dejar ver "más allá" del borde del mundo escalado
    // (fondo negro de .pulperia-scene) salvo que el mundo sea más chico
    // que el visor en ese eje, caso en el que no hay nada que clampear.
    const mundoEscaladoAncho = this.mundoAncho * zoomCamara;
    const mundoEscaladoAlto = this.mundoAlto * zoomCamara;

    const offsetXMin = Math.min(0, rectEscena.width - mundoEscaladoAncho);
    const offsetYMin = Math.min(0, rectEscena.height - mundoEscaladoAlto);

    offsetX = Math.min(0, Math.max(offsetXMin, offsetX));
    offsetY = Math.min(0, Math.max(offsetYMin, offsetY));

    this.elementos.mundoMapa.style.transform =
      `translate(${offsetX}px, ${offsetY}px) scale(${zoomCamara})`;
  }

  /**
   * Revisa la distancia del jugador a cada personaje, marca visualmente
   * cuál está cerca (o bloqueado, si es el Baqueano y todavía faltan los
   * otros tres) y actualiza el cartel de ayuda.
   */
  actualizarProximidad() {
    const jugadorAlto = this.elementos.jugadorMapa.offsetHeight || 80;
    // El jugador y los NPC están anclados por los pies; para proximidad se
    // compara el centro visible de cada sprite, no su esquina ni la cámara.
    const centroJugador = { x: this.posicion.x, y: this.posicion.y - jugadorAlto / 2 };
    let indiceMasCercano = null;
    let menorDistancia = RADIO_INTERACCION_MUNDO;

    const hayObstaculoEntre = (origen, destino) => {
      const distancia = Math.hypot(destino.x - origen.x, destino.y - origen.y);
      const pasos = Math.max(1, Math.ceil(distancia / 12));
      for (let paso = 1; paso < pasos; paso++) {
        const proporcion = paso / pasos;
        const x = origen.x + (destino.x - origen.x) * proporcion;
        const y = origen.y + (destino.y - origen.y) * proporcion;
        if (this.colisionaConEdificio(x, y)) return true;
      }
      return false;
    };

    this.elementos.mundoMapa.querySelectorAll('.personaje').forEach((boton) => {
      const indice = Number(boton.dataset.personaje);
      const esCantor = indice === 3;
      if ((this.dentroPulperia && !esCantor) || (!this.dentroPulperia && esCantor)) {
        boton.classList.remove('personaje-cerca');
        return;
      }
      const yaInterrogado = this.estado.personajesInterrogados.has(indice)
        || ([4, 5, 6].includes(indice) && this.estado.misionBaqueanoHablados?.has(indice));
      boton.classList.toggle('personaje-bloqueado', false);
      if (yaInterrogado) {
        boton.classList.remove('personaje-cerca');
        return;
      }
      const figura = boton.querySelector('.personaje-figura');
      const altoFigura = figura?.offsetHeight || 82;
      const centroBoton = { x: boton.offsetLeft, y: boton.offsetTop - boton.offsetHeight + altoFigura / 2 };
      const puntoApoyoJugador = this.posicion;
      const puntoApoyoBoton = { x: boton.offsetLeft, y: boton.offsetTop };
      const distancia = Math.hypot(centroJugador.x - centroBoton.x, centroJugador.y - centroBoton.y);
      const cerca = distancia <= RADIO_INTERACCION_MUNDO && !hayObstaculoEntre(puntoApoyoJugador, puntoApoyoBoton);
      boton.classList.toggle('personaje-cerca', cerca);
      if (cerca && distancia < menorDistancia) {
        menorDistancia = distancia;
        indiceMasCercano = indice;
      }
    });

    if (indiceMasCercano === this.personajeCercano) return;
    this.personajeCercano = indiceMasCercano;
    if (indiceMasCercano === null) {
      establecerTexto(this.elementos.pistaInteraccion, this.dentroPulperia
        ? (esDispositivoTactil() ? 'ACERCATE AL CANTOR Y PRESIONÁ A PARA HABLAR' : 'ACERCATE AL CANTOR Y PRESIONÁ ESPACIO PARA HABLAR')
        : (esDispositivoTactil() ? 'MOVETE CON EL JOYSTICK Y ACERCATE A UN PERSONAJE · A PARA HABLAR · B PARA PUERTAS' : 'MOVETE CON WASD O LAS FLECHAS Y ACERCATE A UN PERSONAJE'));
      return;
    }
    const nombre = this.elementos.mundoMapa
      .querySelector(`.personaje[data-personaje="${indiceMasCercano}"] .personaje-etiqueta`)
      ?.textContent || '';
    establecerTexto(this.elementos.pistaInteraccion, esDispositivoTactil()
      ? `PRESIONÁ A PARA HABLAR CON ${nombre}`
      : `PRESIONÁ E O ESPACIO PARA HABLAR CON ${nombre}`);
  }
}

export { GestorMapa };
